from dataclasses import dataclass

@dataclass
class Point:
    x: float
    y: float

    def distance_to(self, other):
        return math.hypot(self.x - other.x, self.y - other.y)

print(Point(0, 0).distance_to(Point(3, 4)))  # 5.0
