from functools import wraps

def retry(times=3):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if attempt == times:
                        raise
        return wrapper
    return decorator

calls = 0

@retry(times=3)
def flaky():
    global calls
    calls += 1
    if calls < 3:
        raise ConnectionError("try again")
    return "ok"

print(flaky(), calls)  # ok 3
```

