Accept a tuple of exception types and catch only those, so anything else propagates at once:

```python
from functools import wraps

def retry(times=3, on=(Exception,)):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for attempt in range(1, times + 1):
                try:
                    return func(*args, **kwargs)
                except on:
                    if attempt == times:
                        raise
        return wrapper
    return decorator

@retry(times=3, on=(ConnectionError, TimeoutError))
def broken():
    raise TypeError("bad argument")

try:
    broken()
except TypeError as e:
    print("not retried:", e)  # not retried: bad argument
```

`except` accepts a tuple of classes, so `except on:` matches any of them and their subclasses.

```python
from collections import deque

def shortest_path(graph, start, goal):
    prev = {start: None}
    queue = deque([start])
    while queue:
        node = queue.popleft()
        if node == goal:
            path = []
            while node is not None:
                path.append(node)
                node = prev[node]
            return path[::-1]
        for nb in graph.get(node, []):
            if nb not in prev:
                prev[nb] = node
                queue.append(nb)
    return None

g = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": ["E"]}
print(shortest_path(g, "A", "E"))  # ['A', 'C', 'E']
```

Breadth-first search visits nodes in order of distance, so the first time it reaches the goal, it got there by a shortest path. `prev` records how each node was reached; walking it backwards rebuilds the path.

